head.script:
// Interactive Lightbox Engine
window.openLightbox = function(src) {
  var modal = document.getElementById('lightboxModal');
  var img = document.getElementById('lightboxImg');
  if (modal && img) {
    img.src = src;
    modal.classList.add('open');
    if (typeof playSynthSound === 'function') playSynthSound(850, 'sine', 0.15);
  }
};

window.closeLightbox = function(e) {
  var modal = document.getElementById('lightboxModal');
  if (modal && (e.target.id === 'lightboxModal' || e.target.id === 'lightboxClose' || e.target.closest('#lightboxClose'))) {
    modal.classList.remove('open');
    if (typeof playSynthSound === 'function') playSynthSound(400, 'sine', 0.1);
  }
};

document.addEventListener('DOMContentLoaded', function() {
  // Attach Lightbox click to all gallery and techno images
  document.querySelectorAll('.gallery-item img, .techno-gallery img, .cert-hero-image img, .experience-media img').forEach(function(img) {
    img.style.cursor = 'zoom-in';
    img.addEventListener('click', function() {
      window.openLightbox(img.src);
    });
  });
});


// Native High-Performance Intersection Observer for Scroll Animations
document.addEventListener('DOMContentLoaded', function() {
  // Add reveal-on-scroll class to all sections and main cards
  document.querySelectorAll('section, .hero-grid, .about-grid, .robovai-grid, .contact-grid, .techno-grid, .terminal-window').forEach(function(el) {
    el.classList.add('reveal-on-scroll');
  });

  var observer = new IntersectionObserver(function(entries) {
    entries.forEach(function(entry) {
      if (entry.isIntersecting) {
        entry.target.classList.add('is-visible');
      }
    });
  }, {
    threshold: 0.12,
    rootMargin: '0px 0px -40px 0px'
  });

  document.querySelectorAll('.reveal-on-scroll').forEach(function(el) {
    observer.observe(el);
  });
});

// Case Study Switcher Functionality
window.switchCaseStudy = function(type) {
  var container = document.getElementById('caseStudyContent');
  var btns = document.querySelectorAll('#case-studies .sim-btn');
  btns.forEach(function(b) { b.classList.remove('active'); });

  if (!container) return;
  if (typeof playSynthSound === 'function') playSynthSound(650, 'sine', 0.12);

  var data = {
    'robovai': {
      title_en: 'RoboVAI Nova & Boost Orchestration Engine',
      title_ar: 'محرك تسيير وتوجيه RoboVAI Nova & Boost',
      subtitle_en: 'Autonomous AI Agent Infrastructure for Enterprise Operations',
      subtitle_ar: 'بنية تحتية لإدارة وكلاء الذكاء الاصطناعي في الشركات',
      url: 'https://robovai.tech',
      desc_en: 'Designed and implemented a multi-agent control layer that governs autonomous decision-making, LLM tool-calling, policy guardrails, and automated escalation paths for business teams.',
      desc_ar: 'بناء وتصميم معمارية محرك RoboVAI Nova لإدارة صلاحيات وتوجيه الـ AI Agents وأتمتة العمليات المعقدة وتقليل وقت اتخاذ القرار.',
      tags: ['Laravel / PHP', 'Python / FastAPI', 'Vector DB (Qdrant)', 'n8n Pipelines', 'Flutter']
    },
    'mcit': {
      title_en: 'MCIT Digital Transformation & Institutional Development',
      title_ar: 'مبادرات التحول الرقمي بالمكتب الفني - وزارة الاتصالات',
      subtitle_en: 'Technical Office of Deputy Minister (MCIT)',
      subtitle_ar: 'المكتب الفني nنائب وزير الاتصالات للتحول الرقمي',
      url: '#',
      desc_en: 'Researched and monitored Key Performance Indicators (KPIs) for national digital transformation projects, supporting executive decision-making and inter-governmental coordination.',
      desc_ar: 'المساهمة في متابعة مؤشرات الأداء للمشروعات القومية، ودعم اتخاذ القرار وتنسيق مبادرات التحول الرقمي الحكومية.',
      tags: ['Government Digital Policy', 'KPI Benchmarking', 'Data Analytics', 'Institutional Dev']
    },
    'merkato': {
      title_en: 'Merkato Industrial B2B Platform (GESR Award Winner)',
      title_ar: 'منصة Merkato للتداول الصناعي (الفائزة بجائزة جسر)',
      subtitle_en: 'Product Operations & GTM Growth',
      subtitle_ar: 'إطلاق المنصة واستراتيجية الدخول لسوق الـ B2B',
      url: '#',
      desc_en: 'Architected and launched the industrial trading platform from 0 to 1, developing Go-To-Market (GTM) strategy and winning the GESR SaaS innovation competition.',
      desc_ar: 'إطلاق المنصة من الصفر (0 to 1)، تطوير استراتيجية الدخول للسوق (GTM)، والفوز بجائزة مسابقة جسر (GESR) للشركات الناشئة.',
      tags: ['B2B Marketplace', 'SaaS Architecture', 'GTM Strategy', 'GESR Award Winner']
    },
    'techno': {
      title_en: 'Techno Egypt EdTech & Technology Empowerment',
      title_ar: 'مبادرة تكنو إيجيبت لتأهيل وتدريب الشباب',
      subtitle_en: 'General Coordinator — Ministry of Youth Sponsorship',
      subtitle_ar: 'تحت رعاية وزارة الشباب والرياضة ومجلس الشباب',
      url: 'https://www.facebook.com/technoegypt0/',
      desc_en: 'Planned and led comprehensive technology training initiatives, equipping thousands of Egyptian youth with software engineering, AI, and job-market capabilities.',
      desc_ar: 'تخطيط وإدارة برامج التدريب لتأهيل الشباب لسوق العمل التكنولوجي، بالتعاون مع الكيانات الشبابية والمؤسسات التكنولوجية.',
      tags: ['EdTech Infrastructure', 'Youth Leadership', 'Tech Training', 'Ministry Sponsored']
    }
  };

  var item = data[type];
  if (!item) return;

  var tagsHtml = item.tags.map(function(t) { return '<span class="hero-tag" style="color: var(--primary);">' + t + '</span>'; }).join(' ');

  container.innerHTML = '<div class="case-study-pane">' +
    '<div style="display: flex; justify-content: space-between; align-items: flex-start; flex-wrap: wrap; gap: 15px; margin-bottom: 16px;">' +
      '<div>' +
        '<h3 style="color: var(--primary); font-size: 1.4rem; margin-bottom: 4px;">' + item.title_en + '</h3>' +
        '<p style="color: var(--gray); font-size: 0.9rem;"><span class="lang-en">' + item.subtitle_en + '</span><span class="lang-ar">' + item.subtitle_ar + '</span></p>' +
      '</div>' +
      (item.url !== '#' ? '<a href="' + item.url + '" target="_blank" class="btn btn-outline" style="padding: 6px 16px; font-size: 0.82rem;"><span class="lang-en">View Details</span><span class="lang-ar">التفاصيل</span> <i class="fas fa-external-link-alt"></i></a>' : '') +
    '</div>' +
    '<p style="color: #cbd5e1; line-height: 1.7; margin-bottom: 16px;"><span class="lang-en">' + item.desc_en + '</span><span class="lang-ar">' + item.desc_ar + '</span></p>' +
    '<div style="display: flex; gap: 10px; flex-wrap: wrap;">' + tagsHtml + '</div>' +
  '</div>';
};

window.dataLayer = window.dataLayer || [];
      function gtag(){dataLayer.push(arguments);}
      gtag('js', new Date());
      gtag('config', 'G-WKP4SLGYP3');

